/** Who may open this page */
function canOpen(user: SessionUser | null): boolean {
  return user !== null;
}

function AccessGate({ user }: { user: SessionUser | null }) {
  return (
    <div className="mx-auto max-w-md p-6">
      <Card>
        <CardHeader>
          <CardTitle>{user ? "No access" : "Sign in required"}</CardTitle>
          <CardDescription>{user ? "Your account cannot open this page." : "Sign in to open this page."}</CardDescription>
        </CardHeader>
        {user ? null : (
          <CardContent>
            <Link href="/login" className={buttonVariants()}>
              Sign in
            </Link>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

/** Waits for the session, then renders the page or the gate */
function guarded<P extends object>(Component: (props: P) => ReactNode) {
  return function Guarded(props: P) {
    const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
    if (session.isPending) return <PaneSkeleton />;
    const user = sessionUser(session.data);
    if (!canOpen(user)) return <AccessGate user={user} />;
    return <Component {...props} />;
  };
}

const TEAMS_FIELDS = ["name"] as const;
type TeamsField = (typeof TEAMS_FIELDS)[number];

type TeamsValues = {
  name: string;
};

const EMPTY_TEAMS: TeamsValues = {
  name: ""
};

const TEAMS_CREATE: readonly TeamsField[] = ["name"];

function toTeamsCreateInput(v: TeamsValues): Input<"create"> {
  return {
    name: v.name
  };
}

const TEAMS_UPDATE: readonly TeamsField[] = ["name"];

function toTeamsUpdateInput(v: TeamsValues): Input<"update">["data"] {
  return {
    name: v.name
  };
}

function teamsFromRow(row: Detail): TeamsValues {
  return {
    name: text(row.name)
  };
}

type TeamsSetter = <K extends keyof TeamsValues>(key: K, value: TeamsValues[K]) => void;

function renderTeamsField(field: TeamsField, values: TeamsValues, set: TeamsSetter) {
  switch (field) {
    case "name":
      return (
      <FormRow label="Name" htmlFor="name">
        <Input id="name" type="text" maxLength={100} value={values.name} onChange={e => set("name", e.target.value)} required />
      </FormRow>
      );
  }
}

function TeamsForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly TeamsField[];
  initial: TeamsValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: TeamsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<TeamsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: TeamsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderTeamsField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function TeamsLayoutInner({ children }: { children: ReactNode }) {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["teams"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.teams.list(input) });
  const pathname = usePathname();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Teams" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/teams/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New team">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No teams yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    href={`/teams/${text(row.id)}`}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", pathname === `/teams/${text(row.id)}` && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.name) || "Team " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[formatDateTime(row.created_at)].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        {children}
      </section>
    </div>
  );
}

function TeamsIndexInner() {
  return <EmptyPane>Select a team from the list, or create one.</EmptyPane>;
}

function TeamsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.teams.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/teams/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New team">
      <TeamsForm
        fields={TEAMS_CREATE}
        initial={EMPTY_TEAMS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toTeamsCreateInput(values))}
      />
    </Pane>
  );
}

function TeamsDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.teams.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["teams"]["update"]) => client.teams.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["teams"]["delete"]) => client.teams.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/teams");
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.name) || "Team " + text(row.id)}
      actions={
        <>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this team?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <TeamsForm
          fields={TEAMS_UPDATE}
          initial={teamsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toTeamsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Members">
          {row.members.length === 0 ? (
            "—"
          ) : (
            <ul className="space-y-1">
              {row.members.map(item => (
                <li key={text(item.id)}>{text(item.id)}</li>
              ))}
            </ul>
          )}
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}

